function parse(value, fallback) {
  if (value == null) return fallback;
  if (typeof value === 'string') { try { return JSON.parse(value); } catch { return fallback; } }
  return value;
}
const row = $input.first()?.json || {};
if (row.ok === false || row.ok === 'f') {
  return [{ json: { ok: false, retry: false, error: row.error || 'Publication job retry could not be prepared.' } }];
}
return [{ json: { ok: true, retry: true, retryStep: row.retryStep, job: {
  publicationJobId: row.publicationJobId,
  avatar: row.avatar,
  scene: row.scene,
  format: row.format,
  objective: row.objective,
  businessProfile: row.businessProfile,
  assetType: row.assetType,
  status: row.status,
  brief: parse(row.brief, null),
  promptPack: parse(row.promptPack, null),
  publishingPack: parse(row.publishingPack, null),
  publishingExport: parse(row.publishingExport, null),
  publishedRecord: parse(row.publishedRecord, null),
  errorMessage: row.errorMessage,
  createdAt: row.createdAt,
  updatedAt: row.updatedAt
} } }];
